import{_ as e,b as a,c as i,a3 as d}from"./chunks/framework.CVxMWxk-.js";const u=JSON.parse('{"title":"人机验证 Turnstile","description":"","frontmatter":{},"headers":[],"relativePath":"guide/turnstile.md","filePath":"guide/turnstile.md","lastUpdated":1789525229000}'),s={name:"guide/turnstile.md"};function o(l,t,n,r,h,c){return a(),i("div",null,[...t[0]||(t[0]=[d(`<h1 id="人机验证-turnstile" tabindex="-1">人机验证 Turnstile <a class="header-anchor" href="#人机验证-turnstile" aria-label="Permalink to &quot;人机验证 Turnstile&quot;">​</a></h1><p>CWD 评论系统支持接入 Cloudflare Turnstile，在提交评论和回复前要求访客完成一次人机验证，用来阻挡批量刷评的机器人。Turnstile 由 Cloudflare 免费提供，Managed 模式下大多数访客无需任何操作即可通过，也不能被用来追踪访客。</p><p>开启过程分两步：先在 Cloudflare 控制台申请一对密钥，再把密钥配置到 Worker 环境变量。密钥不属于后台设置项，不需要写进数据库。</p><h2 id="申请密钥" tabindex="-1">申请密钥 <a class="header-anchor" href="#申请密钥" aria-label="Permalink to &quot;申请密钥&quot;">​</a></h2><h3 id="前提条件" tabindex="-1">前提条件 <a class="header-anchor" href="#前提条件" aria-label="Permalink to &quot;前提条件&quot;">​</a></h3><ul><li>一个 Cloudflare 账号（使用邮箱即可注册，<a href="https://www.cloudflare.com/" target="_blank" rel="noreferrer">官网地址</a>）</li><li>评论页面所在的域名</li></ul><p>域名不要求托管在 Cloudflare 上，Turnstile 可以独立使用，也不要求站点流量经过 Cloudflare。</p><h3 id="创建-widget" tabindex="-1">创建 Widget <a class="header-anchor" href="#创建-widget" aria-label="Permalink to &quot;创建 Widget&quot;">​</a></h3><ol><li>登录 <a href="https://dash.cloudflare.com/" target="_blank" rel="noreferrer">Cloudflare 控制台</a>，在左侧菜单选择 <strong>Turnstile</strong>，也可以直接访问 <code>https://dash.cloudflare.com/?to=/:account/turnstile</code></li><li>点击 <strong>Add widget</strong></li><li>填写表单： <ul><li><strong>Widget name</strong>：自定义名称，例如 <code>CWD Comments</code></li><li><strong>Hostname management</strong>：评论页面所在的域名，例如 <code>blog.example.com</code>，可以添加多个</li><li><strong>Widget mode</strong>：选择 <strong>Managed</strong>（推荐）</li></ul></li><li>点击 <strong>Create</strong></li><li>页面会显示 <strong>Sitekey</strong> 和 <strong>Secret Key</strong>，Secret Key 只在创建时完整显示，请立即妥善保存</li></ol><p>Widget mode 的可选项：</p><table tabindex="0"><thead><tr><th>模式</th><th>说明</th></tr></thead><tbody><tr><td>Managed</td><td>根据访客风险自动选择无感验证或勾选框验证，推荐使用</td></tr><tr><td>Non-Interactive</td><td>只显示加载状态，不要求访客点击</td></tr><tr><td>Invisible</td><td>完全在后台运行，需要同时在隐私政策中引用 Cloudflare 的相关条款</td></tr></tbody></table><h3 id="免费额度" tabindex="-1">免费额度 <a class="header-anchor" href="#免费额度" aria-label="Permalink to &quot;免费额度&quot;">​</a></h3><p>免费计划足够个人站点和大多数生产环境使用，无需付费升级：</p><table tabindex="0"><thead><tr><th>项目</th><th>免费计划</th></tr></thead><tbody><tr><td>Widget 数量</td><td>每个账号最多 20 个</td></tr><tr><td>Hostname 数量</td><td>每个 Widget 最多 10 个</td></tr><tr><td>验证次数</td><td>不限</td></tr><tr><td>数据分析</td><td>保留 7 天</td></tr></tbody></table><h2 id="配置到评论系统" tabindex="-1">配置到评论系统 <a class="header-anchor" href="#配置到评论系统" aria-label="Permalink to &quot;配置到评论系统&quot;">​</a></h2><p>拿到密钥后，在 Worker 中配置以下环境变量：</p><table tabindex="0"><thead><tr><th>变量名</th><th>对应控制台字段</th><th>配置方式</th></tr></thead><tbody><tr><td><code>TURNSTILE_SITE_KEY</code></td><td>Sitekey</td><td>普通变量，写在 <code>wrangler.jsonc</code> 的 <code>vars</code></td></tr><tr><td><code>TURNSTILE_SECRET_KEY</code></td><td>Secret Key</td><td>Wrangler Secret 或控制台加密变量</td></tr><tr><td><code>TURNSTILE_ALLOWED_HOSTNAMES</code></td><td>Hostname management</td><td>可选，普通变量，多个域名以逗号分隔</td></tr></tbody></table><p>私密密钥建议使用 Wrangler Secret 保存，不会出现在配置文件中：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cwd-api</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wrangler</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> secret</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> put</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> TURNSTILE_SECRET_KEY</span></span></code></pre></div><p>站点密钥和允许域名可以写在 <code>wrangler.jsonc</code> 的 <code>vars</code> 中：</p><div class="language-jsonc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">jsonc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">	&quot;vars&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">		&quot;TURNSTILE_SITE_KEY&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0x4AAAAAAA...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">		&quot;TURNSTILE_ALLOWED_HOSTNAMES&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;blog.example.com,www.example.com&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">	}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>修改 <code>wrangler.jsonc</code> 后需要重新执行 <code>npx wrangler deploy</code> 才会生效，<code>wrangler secret put</code> 则会立即生效。</p><h3 id="前端无需额外配置" tabindex="-1">前端无需额外配置 <a class="header-anchor" href="#前端无需额外配置" aria-label="Permalink to &quot;前端无需额外配置&quot;">​</a></h3><p>服务端同时配置站点密钥和私密密钥后，评论组件会从 <code>/api/config/comments</code> 自动读取 <code>turnstileSiteKey</code>，并在提交新评论和回复前渲染验证码。只有在需要覆盖后端配置时，才需要在前端实例化时传入 <code>turnstileSiteKey</code>，参见<a href="/guide/frontend-config.html">前端配置</a>。</p><h2 id="本地调试" tabindex="-1">本地调试 <a class="header-anchor" href="#本地调试" aria-label="Permalink to &quot;本地调试&quot;">​</a></h2><p>Cloudflare 提供了一组官方测试密钥，可以在本地和测试环境使用，不消耗额度也不会影响真实访客：</p><table tabindex="0"><thead><tr><th>Sitekey</th><th>Secret Key</th><th>效果</th></tr></thead><tbody><tr><td><code>1x00000000000000000000AA</code></td><td><code>1x0000000000000000000000000000000AA</code></td><td>永远验证通过</td></tr><tr><td><code>2x00000000000000000000AB</code></td><td><code>2x0000000000000000000000000000000AA</code></td><td>永远验证失败</td></tr></tbody></table><p>测试密钥在任意域名（包括 <code>localhost</code>）都可以使用。测试 token 的 hostname 不是你的真实域名，因此使用测试密钥时不要配置 <code>TURNSTILE_ALLOWED_HOSTNAMES</code>，否则服务端会因为域名不匹配而拒绝评论。</p><p>本地开发可以写在 <code>cwd-api/.dev.vars</code> 中（该文件已在 <code>.gitignore</code> 中忽略，不会提交）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TURNSTILE_SITE_KEY=1x00000000000000000000AA</span></span>
<span class="line"><span>TURNSTILE_SECRET_KEY=1x0000000000000000000000000000000AA</span></span></code></pre></div><h2 id="校验规则" tabindex="-1">校验规则 <a class="header-anchor" href="#校验规则" aria-label="Permalink to &quot;校验规则&quot;">​</a></h2><p>开启后，服务端会在写入评论前依次完成以下检查：</p><ol><li>请求必须携带 Turnstile token，缺失或不合法时返回 403「请完成人机验证后再提交评论」</li><li>调用 Siteverify 接口校验 token，token 是一次性的，重复使用会被判为无效</li><li>校验结果中的 <code>action</code> 必须为 <code>comment</code>，该动作由评论组件固定传入，无需手动配置</li><li>配置了 <code>TURNSTILE_ALLOWED_HOSTNAMES</code> 时，token 中的 hostname 必须与列表中的某一项完全一致</li></ol><p>Siteverify 接口不可用时返回 503「人机验证服务暂时不可用，请稍后再试」。同一 IP 的冷却检查在校验之前执行，冷却期内的重复提交不会浪费一次性的 token。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><h3 id="评论全部提示「请完成人机验证后再提交评论」" tabindex="-1">评论全部提示「请完成人机验证后再提交评论」 <a class="header-anchor" href="#评论全部提示「请完成人机验证后再提交评论」" aria-label="Permalink to &quot;评论全部提示「请完成人机验证后再提交评论」&quot;">​</a></h3><p>通常是只配置了 <code>TURNSTILE_SECRET_KEY</code> 而漏配 <code>TURNSTILE_SITE_KEY</code>。服务端检测到私密密钥后就会强制校验，而前端拿不到站点密钥、无法渲染验证码，于是所有提交都会被拒绝。两个密钥必须成对配置。</p><h3 id="配置了允许域名后评论被拒绝" tabindex="-1">配置了允许域名后评论被拒绝 <a class="header-anchor" href="#配置了允许域名后评论被拒绝" aria-label="Permalink to &quot;配置了允许域名后评论被拒绝&quot;">​</a></h3><p><code>TURNSTILE_ALLOWED_HOSTNAMES</code> 是精确匹配，不支持通配子域名。<code>example.com</code>、<code>www.example.com</code>、<code>comments.example.com</code> 需要分别列出，并且要与 Widget 的 Hostname management 保持一致。</p><h3 id="如何关闭人机验证" tabindex="-1">如何关闭人机验证 <a class="header-anchor" href="#如何关闭人机验证" aria-label="Permalink to &quot;如何关闭人机验证&quot;">​</a></h3><p>删除 Worker 中的 <code>TURNSTILE_SECRET_KEY</code> 即可。服务端会跳过校验，前端也不再渲染验证码，无需改动前端代码。</p>`,41)])])}const k=e(s,[["render",o]]);export{u as __pageData,k as default};
